      "instructions": [
        "Sałatę lodową (1 szt) porwij na kawałki i ułóż na talerzach.",
        "Mango (1 szt) i awokado (1 szt) obierz i pokrój w kostkę.",
        "Łososia wędzonego (150 g) pokrój na paski.",
        "Ułóż mango, awokado i łososia na sałacie.",
        "Skrop sokiem z limonki (1 szt) i oliwą z oliwek (1 łyżka), dopraw pieprzem.",
      ],
      "suggested_seasonings": ["świeża kolendra"],
    },
    "en_GB": {
      "name": "Smoked salmon, mango and avocado salad",
      "description":
          "A refreshing salad pairing smoked salmon with sweet mango.",
      "instructions": [
        "Tear the iceberg lettuce (1 lettuce) into pieces and arrange on plates.",
        "Peel and dice the mango (1 mango) and avocado (1 avocado).",
        "Cut the smoked salmon (150 g) into strips.",
        "Arrange the mango, avocado and salmon over the lettuce.",
        "Drizzle with lime juice (1 lime) and olive oil (1 tablespoon), then season with pepper.",
      ],
      "suggested_seasonings": ["fresh coriander"],
    },
    "de": {
      "name": "Geräucherter Lachs, Mango- und Avocado-Salat",
      "description":
          "Eine erfrischende Salatpaarung geräucherten Lachs mit süßer Mango.",
      "instructions": [
        "Zupfe den Eisbergsalat (1 Kopf) in Stücke und verteile ihn auf Tellern.",
        "Schälen und würfeln Sie die Mango (1 Mango) und Avocado (1 Avocado).",
        "Schneiden Sie den geräucherten Lachs (150 g) in Streifen.",
        "Ordnen Sie die Mango, Avocado und Lachs über dem Salat.",
        "Drizzle mit Limettensaft (1 Limette) und Olivenöl (1 Esslöffel), dann Saison mit Pfeffer.",
      ],
      "suggested_seasonings": ["Koriander, frisch"],
    },
  },
  "fc97571c-29fe-5f11-bee8-2991bea1041e": {
    "source": {
      "name": "Makaron z brokułem w sosie śmietanowym",
      "description":
          "Kremowy makaron z brokułem i parmezanem. sycący wegetariański obiad.",
      "instructions": [
        "Ugotuj makaron penne (180 g) w osolonej wodzie zgodnie z instrukcją na opakowaniu.",
        "Brokuł (1 szt) podziel na różyczki i ugotuj na parze przez 5 minut.",
        "Na patelni podduś drobno posiekany czosnek (2 szt) na maśle extra (15 g).",
        "Dodaj śmietanę 30% (150 ml) i podgrzewaj, mieszając, aż lekko zgęstnieje.",
        "Dodaj makaron, brokuł oraz starty parmezan (40 g), wymieszaj i dopraw solą i pieprzem.",
      ],
      "suggested_seasonings": ["gałka muszkatołowa"],
    },
    "en_GB": {
      "name": "Pasta with broccoli in a cream sauce",
      "description":
          "Creamy pasta with broccoli and Parmesan — a filling vegetarian lunch.",
      "instructions": [
        "Cook the penne (180 g) in salted water according to the packet instructions.",
        "Cut the broccoli (1 broccoli) into florets and steam for 5 minutes.",
        "Gently cook the finely chopped garlic (2 cloves) in butter (15 g) in a frying pan.",
        "Add the 30% cream (150 ml) and heat, stirring, until slightly thickened.",
        "Add the pasta, broccoli and grated Parmesan (40 g), stir and season with salt and pepper.",
      ],
      "suggested_seasonings": ["nutmeg"],
    },
    "de": {
      "name": "Pasta mit Brokkoli in einer cremefarbenen Sauce",
      "description":
          "Cremige Pasta mit Brokkoli und Parmesan - ein füllendes vegetarisches Mittagessen.",
      "instructions": [
        "Kochen Sie den Penne (180 g) in gesalzenem Wasser gemäß den Packungsanweisungen.",
        "Schneiden Sie den Brokkoli (1 Brokkoli) in Blumen und Dampf für 5 Minuten.",
        "Kochen Sie den fein gehackten Knoblauch (2 Nelken) in Butter (15 g) in einer Bratpfanne.",
        "Fügen Sie die 30% Creme (150 ml) hinzu und erhitzen Sie unter Rühren, bis Sie leicht verdickt sind.",
        "Fügen Sie die Pasta, Brokkoli und geriebenen Parmesan (40 g), rühren und würzen Sie mit Salz und Pfeffer.",
      ],
      "suggested_seasonings": ["Muskatnuss"],
    },
  },
  "d790e41d-5ba4-5cae-96c6-332b6db6d5f0": {
