      "suggested_seasonings": ["Paprika, süß", "Kurkuma", "Currypulver"],
    },
  },
  "db344e04-3f19-5a6f-a246-b57588fc012f": {
    "source": {
      "name": "Zupa pomidorowa z makaronem",
      "description":
          "Domowa zupa pomidorowa na passacie, podawana z drobnym makaronem.",
      "instructions": [
        "Zagotuj bulion warzywny w garnku.",
        "Dodaj passatę (500 g) pomidorową i pomidory krojone, zagotuj ponownie.",
        "Dopraw solą (5 g), pieprzem i bazylią, gotuj 10 minut.",
        "Ugotuj osobno drobny makaron (150 g) według instrukcji na opakowaniu.",
        "Dodaj makaron do zupy tuż przed podaniem, ewentualnie z odrobiną śmietany (100 ml).",
