        "oregano",
        "cukier (do zbalansowania kwasowości)",
      ],
    },
    "en_GB": {
      "name": "Tomato soup with pasta",
      "description":
          "Homemade tomato soup made with passata, served with small pasta shapes.",
      "instructions": [
        "Bring the vegetable stock to the boil in a saucepan.",
        "Add the tomato passata (500 g) and chopped tomatoes, then bring back to the boil.",
        "Season with salt (5 g), pepper and basil, and simmer for 10 minutes.",
        "Cook the small pasta shapes (150 g) separately according to the packet instructions.",
        "Add the pasta to the soup just before serving, with a little cream (100 ml) if desired.",
      ],
      "suggested_seasonings": [
        "fresh basil",
        "oregano",
        "sugar (to balance the acidity)",
      ],
    },
    "de": {
      "name": "Tomatensuppe mit Pasta",
      "description":
          "Hausgemachte Tomatensuppe mit Passata, serviert mit kleinen Nudelformen.",
      "instructions": [
        "Den Gemüsebrühe in einem Topf zum Kochen bringen.",
        "Fügen Sie die Tomate passata (500 g) und gehackte Tomaten hinzu und bringen Sie dann zum Kochen zurück.",
        "Saison mit Salz (5 g), Pfeffer und Basilikum, und kochen für 10 Minuten.",
        "Kochen Sie die kleinen Nudelformen (150 g) separat nach den Packungsanweisungen.",
        "Fügen Sie die Nudeln kurz vor dem Servieren mit etwas Creme (100 ml) hinzu, wenn Sie möchten.",
