        "Zucker (um den Säuregehalt auszugleichen)",
      ],
    },
  },
  "b7aef4b2-c6a5-5f65-b09a-35b5fdc51958": {
    "source": {
      "name": "Sałatka z łososiem",
      "description":
          "Lekka sałatka z wędzonym łososiem, ogórkiem i pomidorami.",
      "instructions": [
        "Rozłóż sałatę (0,5 szt.) lodową na talerzu jako bazę.",
        "Pokrój pomidory (200 g) i ogórka w kostkę, dodaj do sałaty.",
        "Ułóż na wierzchu płaty wędzonego łososia (100 g).",
        "Skrop oliwą (20 ml) z oliwek, dopraw solą (2 g) i pieprzem.",
      ],
