  "724873c2-9f8e-540b-b0d8-e174f9bfc567": {
    "source": {
      "name": "Naleśniki z serem",
      "description": "Delikatne naleśniki nadziewane twarogiem z masłem.",
      "instructions": [
        "Wymieszaj mąkę (150 g), jajka i mleko (250 ml) na gładkie ciasto naleśnikowe, dopraw szczyptą soli (2 g).",
        "Smaż cienkie naleśniki na rozgrzanej patelni z odrobiną masła, po 1-2 minuty z każdej strony.",
        "Rozgnieć twaróg (250 g) z odrobiną cukru na nadzienie.",
        "Nakładaj nadzienie na naleśniki, zwijaj i podawaj.",
      ],
      "suggested_seasonings": ["wanilia", "skórka cytrynowa"],
    },
    "en_GB": {
      "name": "Quark-filled pancakes",
      "description":
          "Delicate pancakes filled with quark and made with butter.",
      "instructions": [
        "Mix the flour (150 g), eggs and milk (250 ml) into a smooth pancake batter, and season with a pinch of salt (2 g).",
        "Fry thin pancakes in a hot pan with a little butter for 1-2 minutes on each side.",
        "Mash the quark (250 g) with a little sugar for the filling.",
        "Spread the filling on the pancakes, roll them up and serve.",
      ],
      "suggested_seasonings": ["vanilla", "lemon zest"],
    },
    "de": {
      "name": "Quarkgefüllte Pfannkuchen",
      "description":
          "Delikate Pfannkuchen, die mit Quark gefüllt und mit Butter hergestellt wurden.",
      "instructions": [
        "Mischen Sie das Mehl (150 g), Eier und Milch (250 ml) in einen glatten Pfannkuchenteig und würzen Sie mit einer Prise Salz (2 g).",
        "Braten Sie dünne Pfannkuchen in einer heißen Pfanne mit etwas Butter für 1-2 Minuten auf jeder Seite.",
        "Mash das Quark (250 g) mit ein wenig Zucker für die Füllung.",
        "Verbreiten Sie die Füllung auf den Pfannkuchen, rollen Sie sie auf und servieren Sie.",
      ],
      "suggested_seasonings": ["Vanille", "Zitronenzeste"],
    },
  },
  "c5ac116e-8f12-5012-87bb-5463dfc3bbc1": {
    "source": {
      "name": "Tosty z jajkiem i awokado",
      "description": "Chrupiące tosty z jajkiem sadzonym i kremowym awokado.",
      "instructions": [
        "Opiecz kromki chleba (200 g) w tosterze lub na suchej patelni.",
        "Rozgnieć miąższ awokado (1 szt.) widelcem, dopraw solą (2 g), pieprzem i sokiem z cytryny.",
        "Usmaż jajko (2 szt.) sadzone na maśle.",
        "Posmaruj tosty awokado i połóż na wierzchu jajko.",
      ],
      "suggested_seasonings": ["płatki chili", "papryka wędzona"],
    },
    "en_GB": {
      "name": "Egg and avocado toast",
      "description": "Crisp toast with fried eggs and creamy avocado.",
      "instructions": [
        "Toast the bread slices (200 g) in a toaster or dry frying pan.",
        "Mash the avocado flesh (1 avocado) with a fork and season with salt (2 g), pepper and lemon juice.",
        "Fry the eggs (2 eggs) in butter.",
        "Spread the avocado on the toast and top with the eggs.",
      ],
      "suggested_seasonings": ["chilli flakes", "smoked paprika"],
    },
    "de": {
      "name": "Egg und Avocado Toast",
      "description":
          "Knuspriger Toast mit gebratenen Eiern und cremiger Avocado.",
      "instructions": [
        "Braten Sie die Brotscheiben (200 g) in einem Toaster oder einer trockenen Bratpfanne.",
        "Mash die Avocado-Fleisch (1 Avocado) mit einer Gabel und Saison mit Salz (2 g), Pfeffer und Zitronensaft.",
        "Frittieren Sie die Eier (2 Eier) in Butter.",
        "Verbreiten Sie die Avocado auf dem Toast und oben mit den Eiern.",
      ],
      "suggested_seasonings": ["Chili-Flocken", "geräucherte Paprika"],
    },
  },
  "28fc4da5-422c-5382-8ada-5ef1baa38a2c": {
    "source": {
      "name": "Shakshuka",
      "description":
          "Jajka gotowane w pikantnym sosie pomidorowym z papryką i cebulą.",
      "instructions": [
        "Cebulę (100 g) pokrój w drobną kostkę, czosnek (2 ząbki) drobno posiekaj.",
        "Rozgrzej oliwę (30 ml) na patelni z wysokim brzegiem (żeby jajka się zmieściły), podsmaż cebulę i czosnek 3-4 minuty, aż zmiękną.",
        "Paprykę pokrój w kostkę, dodaj do patelni i smaż kolejne 3-4 minuty.",
        "Wlej pomidory krojone (400 g), dopraw papryką słodką, solą i pieprzem, gotuj na średnim ogniu 10 minut, aż sos lekko zgęstnieje.",
        "Łyżką zrób w sosie 4 wgłębienia i delikatnie wbij do każdego po jednym jajku (4 szt. łącznie).",
        "Przykryj patelnię i gotuj na małym ogniu 6-8 minut — białko powinno być ścięte, żółtko lekko płynne (dłużej, jeśli lubisz twardsze).",
        "Podawaj od razu, prosto z patelni, najlepiej z kawałkiem świeżego pieczywa do maczania.",
      ],
      "suggested_seasonings": [
        "kmin rzymski",
        "papryka wędzona",
        "chili w płatkach",
      ],
    },
    "en_GB": {
      "name": "Shakshuka",
      "description":
          "Eggs cooked in a spicy tomato sauce with pepper and onion.",
      "instructions": [
        "Finely dice the onion (100 g) and finely chop the garlic (2 cloves).",
        "Heat the olive oil (30 ml) in a deep-sided frying pan with room for the eggs. Fry the onion and garlic for 3-4 minutes until soft.",
        "Dice the pepper, add to the pan and fry for another 3-4 minutes.",
        "Pour in the chopped tomatoes (400 g), season with sweet paprika, salt and pepper, and simmer over a medium heat for 10 minutes until slightly thickened.",
        "Make 4 wells in the sauce with a spoon and carefully crack an egg into each (4 eggs in total).",
        "Cover the pan and cook over a low heat for 6-8 minutes. The whites should be set and the yolks slightly runny; cook longer if you prefer them firmer.",
        "Serve straight away from the pan, preferably with fresh bread for dipping.",
      ],
      "suggested_seasonings": ["cumin", "smoked paprika", "chilli flakes"],
    },
    "de": {
      "name": "Shakshuka",
      "description":
          "Eier in einer würzigen Tomatensauce mit Pfeffer und Zwiebeln gekocht.",
      "instructions": [
        "Die Zwiebel (100 g) fein würfeln und den Knoblauch (2 Nelken) fein hacken.",
        "Das Olivenöl (30 ml) wird in einer tiefen Bratpfanne mit Eiern erhitzt; die Zwiebel und der Knoblauch werden 3-4 Minuten lang gebraten, bis sie weich sind.",
        "Würfeln Sie den Pfeffer, fügen Sie die Pfanne hinzu und braten Sie weitere 3-4 Minuten.",
        "Gießen Sie in die gehackten Tomaten (400 g), Saison mit süßem Paprika, Salz und Pfeffer, und köcheln über eine mittlere Hitze für 10 Minuten, bis leicht verdickt.",
        "Machen Sie 4 Brunnen in der Sauce mit einem Löffel und knacken Sie vorsichtig ein Ei in jedes (4 Eier insgesamt).",
        "Bedecke die Pfanne und koche bei niedriger Hitze für 6-8 Minuten. Die Weißtöne sollten eingestellt sein und das Gelb etwas flüssig; koche länger, wenn du sie fester bevorzugst.",
        "Servieren Sie sofort von der Pfanne, vorzugsweise mit frischem Brot zum Tauchen.",
      ],
      "suggested_seasonings": [
        "Kreuzkümmel",
        "geräucherte Paprika",
        "Chili-Flocken",
      ],
    },
  },
  "398c64af-a143-5970-81ce-a7a658698267": {
    "source": {
      "name": "Pad Thai z kurczakiem",
      "description":
          "Klasyczny tajski makaron smażony z kurczakiem, orzeszkami i limonką.",
      "instructions": [
        "Makaron ryżowy (200 g) namocz w ciepłej wodzie zgodnie z instrukcją na opakowaniu (zwykle 10-15 minut), aż zmięknie, odcedź.",
        "Kurczaka (300 g) pokrój w cienkie paski.",
        "Rozgrzej olej na dużej patelni na średnio-wysokim ogniu, podsmaż kurczaka 5-6 minut, mieszając, aż będzie biały w środku — sprawdź, przekrawając największy kawałek. Odłóż na talerz.",
        "Na tej samej patelni podsmaż czosnek i warzywa 2-3 minuty, aż lekko zmiękną, ale zostaną chrupiące.",
        "Dodaj namoczony makaron, usmażonego kurczaka i sos sojowy (30 ml), smaż 2-3 minuty, ciągle mieszając.",
        "Podawaj od razu na gorąco, posyp prażonymi orzechami dla chrupkości.",
      ],
      "suggested_seasonings": [
        "chili w płatkach",
        "prażone orzeszki ziemne",
        "limonka",
      ],
    },
    "en_GB": {
      "name": "Chicken Pad Thai",
      "description":
          "Classic Thai stir-fried noodles with chicken, peanuts and lime.",
      "instructions": [
        "Soak the rice noodles (200 g) in warm water according to the packet instructions, usually 10-15 minutes, until soft, then drain.",
        "Cut the chicken (300 g) into thin strips.",
        "Heat the oil in a large frying pan over a medium-high heat. Stir-fry the chicken for 5-6 minutes until white inside; check by cutting through the largest piece. Transfer to a plate.",
        "In the same pan, fry the garlic and vegetables for 2-3 minutes until slightly softened but still crunchy.",
        "Add the soaked noodles, cooked chicken and soy sauce (30 ml), then stir-fry for 2-3 minutes, stirring constantly.",
        "Serve hot straight away, sprinkled with roasted nuts for crunch.",
      ],
      "suggested_seasonings": ["chilli flakes", "roasted peanuts", "lime"],
    },
    "de": {
      "name": "Chicken Pad Thai",
      "description":
          "Klassische thailändische rührbratene Nudeln mit Huhn, Erdnüssen und Limette.",
      "instructions": [
        "Weichen Sie die Reisnudeln (200 g) in warmem Wasser nach den Packungsanweisungen, in der Regel 10-15 Minuten, bis weich, dann abtropfen.",
        "Schneiden Sie das Huhn (300 g) in dünne Streifen.",
        "Das Öl wird in einer großen Bratpfanne bei mittelhoher Hitze erhitzt, das Huhn für 5-6 Minuten rühren gelassen, bis es weiß ist; das größte Stück durchschneiden und auf einen Teller geben.",
        "In der gleichen Pfanne braten Sie den Knoblauch und das Gemüse für 2-3 Minuten, bis sie leicht erweicht, aber immer noch knusprig sind.",
        "Fügen Sie die getränkten Nudeln, gekochtes Huhn und Sojasauce (30 ml) hinzu, dann rühren Sie für 2-3 Minuten und rühren Sie ständig.",
        "Servieren Sie sofort heiß, bestreut mit gerösteten Nüssen zum Knirschen.",
      ],
      "suggested_seasonings": [
        "Chili-Flocken",
        "geröstete Erdnüsse",
        "Limette",
      ],
    },
  },
  "5b86bd7a-2211-5b46-afbe-5a577c6797a7": {
    "source": {
      "name": "Bowl z quinoa i awokado",
      "description":
          "Zdrowa miska z quinoa, świeżym awokado, pomidorkami i hummusem.",
      "instructions": [
        "Ugotuj quinoa (100 g) w osolonej wodzie według instrukcji na opakowaniu, ostudź.",
        "Pokrój awokado (1 szt.) w plastry, a pomidory w ćwiartki.",
        "Ułóż quinoa w misce, dodaj awokado, pomidory i inne dodatki.",
        "Skrop oliwą (15 ml) z oliwek i sokiem z cytryny, dopraw solą i pieprzem.",
      ],
      "suggested_seasonings": [
        "kmin rzymski",
        "sok z limonki",
        "kolendra świeża",
      ],
    },
    "en_GB": {
      "name": "Quinoa and avocado bowl",
      "description":
          "A healthy bowl with quinoa, fresh avocado, tomatoes and hummus.",
      "instructions": [
        "Cook the quinoa (100 g) in salted water according to the packet instructions and leave to cool.",
        "Slice the avocado (1 avocado) and quarter the tomatoes.",
        "Place the quinoa in a bowl and add the avocado, tomatoes and other toppings.",
        "Drizzle with olive oil (15 ml) and lemon juice, then season with salt and pepper.",
      ],
      "suggested_seasonings": ["cumin", "lime juice", "fresh coriander"],
    },
    "de": {
      "name": "Quinoa und Avocado Bowl",
      "description":
          "Eine gesunde Schüssel mit Quinoa, frischer Avocado, Tomaten und Hummus.",
      "instructions": [
        "Kochen Sie die Quinoa (100 g) in gesalzenem Wasser nach den Packungsanweisungen und lassen Sie sie abkühlen.",
        "Schneiden Sie die Avocado (1 Avocado) und Viertel der Tomaten.",
        "Legen Sie die Quinoa in eine Schüssel und fügen Sie die Avocado, Tomaten und andere Toppings hinzu.",
        "Drizzle mit Olivenöl (15 ml) und Zitronensaft, dann würzen Sie mit Salz und Pfeffer.",
      ],
      "suggested_seasonings": [
        "Kreuzkümmel",
        "Limettensaft",
        "Koriander, frisch",
      ],
    },
  },
  "77999fdc-bd24-501e-b186-fa3272960311": {
    "source": {
      "name": "Risotto z grzybami leśnymi",
      "description":
          "Kremowe risotto z mieszanką grzybów leśnych i parmezanem.",
      "instructions": [
        "Cebulę (100 g) drobno pokrój. Bulion (1 kostka) rozpuść w garnku z gorącą wodą i trzymaj na małym ogniu — risotto lubi gorący bulion.",
        "Na patelni rozpuść masło, wrzuć cebulę i smaż 3-4 minuty, aż zmięknie.",
        "Dodaj pokrojone pieczarki (200 g), smaż 4-5 minut, aż zmiękną i puszczą wodę, która potem odparuje.",
        "Wsyp ryż, smaż 1-2 minuty mieszając — ziarna powinny zrobić się szkliste na brzegach.",
        "Dolej chochlę gorącego bulionu, mieszaj, aż ryż go wchłonie, dopiero wtedy dolej kolejną.",
        "Powtarzaj dolewanie bulionu porcjami przez ok. 18-20 minut, cały czas mieszając — to uwalnia skrobię i daje kremową konsystencję.",
        "Sprawdzaj ryż pod koniec: powinien być miękki, ale z lekkim oporem w środku (al dente).",
        "Zdejmij z ognia, dopraw solą i pieprzem, wmieszaj łyżkę masła (30 g) dla połysku i kremowości. Podawaj od razu.",
      ],
      "suggested_seasonings": ["tymianek", "gałka muszkatołowa"],
    },
    "en_GB": {
      "name": "Wild mushroom risotto",
      "description": "Creamy risotto with mixed wild mushrooms and Parmesan.",
      "instructions": [
        "Finely chop the onion (100 g). Dissolve the stock (1 cube) in a saucepan of hot water and keep over a low heat — risotto needs hot stock.",
        "Melt the butter in a frying pan, add the onion and fry for 3-4 minutes until soft.",
        "Add the sliced mushrooms (200 g) and fry for 4-5 minutes until softened and their released liquid has evaporated.",
        "Add the rice and fry for 1-2 minutes, stirring, until the edges of the grains turn translucent.",
        "Add a ladleful of hot stock and stir until absorbed before adding the next.",
        "Keep adding stock in batches for about 18-20 minutes, stirring constantly to release the starch and create a creamy texture.",
        "Check the rice towards the end: it should be tender but retain a little bite in the centre (al dente).",
        "Remove from the heat, season with salt and pepper, and stir in a spoonful of butter (30 g) for shine and creaminess. Serve immediately.",
      ],
      "suggested_seasonings": ["thyme", "nutmeg"],
    },
    "de": {
      "name": "Wildpilz-Risotto",
      "description": "Cremiges Risotto mit gemischten Wildpilzen und Parmesan.",
      "instructions": [
        "Die Zwiebel fein zerhacken (100 g); den Vorrat (1 Würfel) in einem Kochtopf mit heißem Wasser auflösen und eine geringe Hitze aufbewahren — Risotto braucht heißen Vorrat.",
        "Schmelzen Sie die Butter in einer Bratpfanne, fügen Sie die Zwiebel hinzu und braten Sie für 3-4 Minuten bis weich.",
        "Die in Scheiben geschnittenen Pilze (200 g) werden hinzugefügt und für 4-5 Minuten gebraten, bis sie erweicht sind und ihre freigesetzte Flüssigkeit verdampft ist.",
        "Reis und Braten für 1-2 Minuten unter Rühren hinzufügen, bis die Ränder der Körner lichtdurchlässig werden.",
        "Fügen Sie eine Pfanne mit heißem Stamm hinzu und rühren Sie bis zur Absorption, bevor Sie die nächste hinzufügen.",
        "Fügen Sie den Vorrat in Chargen für etwa 18-20 Minuten hinzu und rühren Sie ständig, um die Stärke freizusetzen und eine cremige Textur zu erzeugen.",
        "Überprüfen Sie den Reis gegen Ende: Er sollte zart sein, aber einen kleinen Biss in der Mitte (al dente) behalten.",
        "Von der Hitze abziehen, mit Salz und Pfeffer würzen und in einem Löffel Butter (30 g) für Glanz und Cremigkeit rühren.",
      ],
      "suggested_seasonings": ["Thymian", "Muskatnuss"],
    },
  },
  "7e2019e7-4d18-554b-867f-04227f3f6269": {
    "source": {
      "name": "Overnight oats z chia i owocami",
      "description":
          "Owsianka przygotowana wieczorem. rano gotowa do jedzenia z owocami.",
      "instructions": [
        "Wymieszaj płatki owsiane (80 g), nasiona chia (20 g) i mleko migdałowe w słoiku.",
        "Zamieszaj dokładnie, przykryj i odstaw do lodówki na całą noc.",
        "Rano wymieszaj ponownie i dodaj świeże owoce (maliny, banana (1 szt.)) na wierzch.",
      ],
      "suggested_seasonings": ["cynamon", "wanilia"],
    },
    "en_GB": {
      "name": "Overnight oats with chia and fruit",
      "description":
          "Oats prepared in the evening — ready to eat with fruit in the morning.",
      "instructions": [
        "Mix the oats (80 g), chia seeds (20 g) and almond milk in a jar.",
        "Stir thoroughly, cover and refrigerate overnight.",
        "In the morning, stir again and top with fresh fruit (raspberries and banana (1 banana)).",
      ],
      "suggested_seasonings": ["cinnamon", "vanilla"],
    },
    "de": {
      "name": "Übernachtung Hafer mit Chia und Obst",
      "description":
          "Am Abend zubereiteter Hafer - bereit, morgens mit Obst zu essen.",
      "instructions": [
        "Mischen Sie den Hafer (80 g), Chiasamen (20 g) und Mandelmilch in einem Glas.",
        "Gründlich rühren, abdecken und über Nacht kühlen.",
        "Morgens wieder umrühren und mit frischen Früchten (Himbeeren und Banane (1 Banane)) auffüllen.",
      ],
      "suggested_seasonings": ["Zimt", "Vanille"],
    },
  },
  "589e0c80-ba08-599b-ade4-3de652e05695": {
    "source": {
      "name": "Jajka na twardo z awokado i tostem",
      "description": "Pożywne śniadanie białkowe z kremowym awokado.",
      "instructions": [
        "Ugotuj jajka (4 szt.) na twardo (ok. 9 minut od zagotowania), ostudź i obierz.",
        "Opiecz kromki chleba (100 g) w tosterze.",
        "Rozgnieć awokado (1 szt.) widelcem, dopraw solą (2 g).",
        "Posmaruj tosty awokado i podawaj z pokrojonymi jajkami.",
      ],
      "suggested_seasonings": ["płatki chili", "szczypiorek"],
    },
    "en_GB": {
      "name": "Hard-boiled eggs with avocado and toast",
      "description": "A nourishing protein breakfast with creamy avocado.",
      "instructions": [
        "Hard-boil the eggs (4 eggs) for about 9 minutes from boiling, then cool and peel.",
        "Toast the bread slices (100 g) in a toaster.",
        "Mash the avocado (1 avocado) with a fork and season with salt (2 g).",
        "Spread the avocado on the toast and serve with the sliced eggs.",
      ],
      "suggested_seasonings": ["chilli flakes", "chives"],
