  "569057a6-85a0-5cd8-b8e3-eb4a63519ab7": {
    "source": {
      "name": "Tost francuski z cynamonem",
      "description":
          "Słodkie śniadanie na weekend. chrupiący na zewnątrz, miękki w środku.",
      "instructions": [
        "Roztrzep jajka (2 szt.) z mlekiem (100 ml) i cynamonem w płaskim naczyniu.",
        "Namocz kromki chleba (150 g) w mieszance z obu stron przez chwilę.",
        "Smaż na maśle na złoty kolor, po 2 minuty z każdej strony.",
        "Podawaj od razu, można posypać cukrem lub polać miodem.",
      ],
      "suggested_seasonings": ["wanilia", "gałka muszkatołowa"],
    },
    "en_GB": {
      "name": "Cinnamon French toast",
      "description":
          "A sweet weekend breakfast — crisp outside and soft inside.",
      "instructions": [
        "Beat the eggs (2 eggs) with milk (100 ml) and cinnamon in a shallow dish.",
        "Briefly soak both sides of the bread slices (150 g) in the mixture.",
        "Fry in butter until golden, for 2 minutes on each side.",
        "Serve immediately, sprinkled with sugar or drizzled with honey if desired.",
      ],
      "suggested_seasonings": ["vanilla", "nutmeg"],
    },
    "de": {
      "name": "Cinnamon Französisch Toast",
      "description":
          "Ein süßes Wochenendfrühstück - draußen knusprig und innen weich.",
      "instructions": [
        "Beat die Eier (2 Eier) mit Milch (100 ml) und Zimt in einer flachen Schale.",
        "Weichen Sie beide Seiten der Brotscheiben (150 g) kurz in die Mischung ein.",
        "Braten Sie in Butter bis golden, für 2 Minuten auf jeder Seite.",
        "Sofort servieren, mit Zucker bestreuen oder gewünschtenfalls mit Honig berieseln.",
      ],
      "suggested_seasonings": ["Vanille", "Muskatnuss"],
    },
  },
  "c31d2370-9494-544c-aafc-93c4c8359d8b": {
