  "9478a09e-09d6-56a9-abb2-2311261441b9": {
    "source": {
      "name": "Jajka sadzone z pomidorami i bazylią",
      "description": "Proste śniadanie na patelni. gotowe w 10 minut.",
      "instructions": [
        "Rozgrzej masło (10 g) na patelni, podsmaż pokrojone pomidory 3 minuty.",
        "Wbij jajka (2 szt.) bezpośrednio na patelnię między pomidory.",
        "Smaż pod przykryciem 3-4 minuty do ulubionego stopnia ścięcia.",
        "Posyp bazylią (1 g) i podawaj od razu.",
      ],
      "suggested_seasonings": ["świeży oregano", "chili w płatkach"],
    },
    "en_GB": {
      "name": "Fried eggs with tomatoes and basil",
      "description": "A simple pan-cooked breakfast — ready in 10 minutes.",
      "instructions": [
        "Heat the butter (10 g) in a frying pan and fry the chopped tomatoes for 3 minutes.",
        "Crack the eggs (2 eggs) directly into the pan between the tomatoes.",
        "Cook, covered, for 3-4 minutes until set to your liking.",
        "Sprinkle with basil (1 g) and serve immediately.",
      ],
      "suggested_seasonings": ["fresh oregano", "chilli flakes"],
    },
    "de": {
      "name": "Gebratene Eier mit Tomaten und Basilikum",
      "description":
          "Ein einfaches, pan-gekochtes Frühstück – bereit in 10 Minuten.",
      "instructions": [
        "Erhitzen Sie die Butter (10 g) in einer Bratpfanne und braten Sie die gehackten Tomaten für 3 Minuten.",
        "Crack die Eier (2 Eier) direkt in die Pfanne zwischen den Tomaten.",
        "Kochen, abgedeckt, für 3-4 Minuten, bis Sie nach Ihren Wünschen eingestellt sind.",
        "Streuen Sie mit Basilikum (1 g) und dienen Sie sofort.",
