  "d0b29f2a-2e29-5346-9add-80a00f261a2e": {
    "source": {
      "name": "Kurczak curry z ryżem",
      "description": "Aromatyczne curry z mlekiem kokosowym. łagodne i sycące.",
      "instructions": [
        "Kurczaka (500 g) pokrój w kostkę ok. 2 cm, cebulę (100 g) w drobną kostkę.",
        "Rozgrzej olej na patelni, wrzuć kurczaka i cebulę, smaż 6-8 minut mieszając, aż kurczak zrumieni się z każdej strony.",
        "Dodaj curry w proszku (10 g), smaż mieszając 1 minutę — przyprawa powinna zacząć intensywnie pachnieć.",
        "Wlej mleko kokosowe (400 ml), wymieszaj, zmniejsz ogień i duś bez przykrycia 15 minut, aż sos zgęstnieje.",
        "W międzyczasie ugotuj ryż (250 g) według instrukcji na opakowaniu.",
        "Sprawdź, czy kurczak jest wysmażony, przekrawając największy kawałek — w środku nie może być różowy.",
        "Podawaj curry na ryżu, od razu na gorąco.",
      ],
      "suggested_seasonings": [
        "kolendra świeża",
        "chili w płatkach",
        "imbir mielony",
      ],
    },
    "en_GB": {
      "name": "Chicken curry with rice",
      "description": "A fragrant coconut milk curry — mild and filling.",
      "instructions": [
        "Cut the chicken (500 g) into cubes about 2 cm across, and finely dice the onion (100 g).",
        "Heat the oil in a frying pan, add the chicken and onion, and fry for 6-8 minutes, stirring, until the chicken is browned on all sides.",
        "Add the curry powder (10 g) and fry, stirring, for 1 minute until strongly fragrant.",
        "Pour in the coconut milk (400 ml), stir, reduce the heat and simmer uncovered for 15 minutes until the sauce thickens.",
        "Meanwhile, cook the rice (250 g) according to the packet instructions.",
        "Check the chicken is cooked by cutting through the largest piece — it must not be pink inside.",
        "Serve the curry over the rice, hot and straight away.",
      ],
      "suggested_seasonings": [
        "fresh coriander",
        "chilli flakes",
        "ground ginger",
      ],
    },
    "de": {
      "name": "Chicken Curry mit Reis",
      "description": "Ein duftendes Kokosmilch-Curry - mild und sättigend.",
      "instructions": [
        "Schneiden Sie das Huhn (500 g) in Würfel etwa 2 cm über, und fein würfeln die Zwiebel (100 g).",
        "Erhitzen Sie das Öl in einer Bratpfanne, fügen Sie das Huhn und die Zwiebel hinzu und braten Sie für 6-8 Minuten unter Rühren, bis das Huhn auf allen Seiten gebräunt ist.",
        "Das Currypulver (10 g) wird zugegeben und unter Rühren für 1 Minute gebraten, bis es stark duftet.",
        "Gießen Sie in die Kokosmilch (400 ml), rühren, reduzieren Sie die Hitze und köcheln Sie für 15 Minuten, bis die Soße sich verdickt.",
        "Währenddessen kochen Sie den Reis (250 g) gemäß den Packungsanweisungen.",
        "Überprüfen Sie, ob das Huhn gekocht wird, indem Sie das größte Stück durchschneiden - es darf nicht rosa sein.",
        "Servieren Sie das Curry über den Reis, heiß und sofort.",
      ],
      "suggested_seasonings": [
        "Koriander, frisch",
        "Chili-Flocken",
        "gemahlener Ingwer",
      ],
    },
  },
  "d2c365e5-eb1b-51d3-9d87-40ed496f9f2a": {
    "source": {
      "name": "Gulasz wołowo-wieprzowy",
      "description": "Gęsty, rozgrzewający gulasz duszony powoli.",
      "instructions": [
        "Cebulę (200 g) pokrój w kostkę, mięso pokrój na kawałki wielkości ok. 2-3 cm.",
        "Rozgrzej olej w garnku z grubym dnem, podsmaż cebulę 3-4 minuty, aż zmięknie.",
        "Dodaj mięso i smaż 5-7 minut, aż każdy kawałek zbrązowieje z każdej strony — to nadaje gulaszowi głębszy smak.",
        "Dodaj paprykę słodką (5 g), wymieszaj i smaż tylko 1 minutę (dłużej może zgorzknieć).",
        "Wlej passatę (300 g) i tyle wody, żeby mięso było prawie przykryte, przykryj garnek.",
        "Zmniejsz ogień i duś 25 minut — mięso powinno łatwo rozpadać się pod widelcem (twardsze kawałki mogą potrzebować więcej czasu).",
        "Osobno ugotuj obrane ziemniaki (400 g) w osolonej wodzie 15-20 minut, aż zmiękną.",
        "Podawaj gulasz z ziemniakami, dopraw solą i pieprzem do smaku.",
      ],
      "suggested_seasonings": [
        "papryka słodka",
        "kminek",
        "majeranek",
        "liść laurowy",
      ],
    },
    "en_GB": {
      "name": "Beef and pork stew",
      "description": "A thick, warming, slow-simmered stew.",
      "instructions": [
        "Dice the onion (200 g) and cut the meat into pieces about 2-3 cm across.",
        "Heat the oil in a heavy-based saucepan and fry the onion for 3-4 minutes until soft.",
        "Add the meat and fry for 5-7 minutes until each piece is browned on all sides, giving the stew a deeper flavour.",
        "Add the sweet paprika (5 g), stir and fry for only 1 minute; cooking it longer can make it bitter.",
        "Pour in the passata (300 g) and enough water to almost cover the meat, then cover the saucepan.",
        "Reduce the heat and simmer for 25 minutes. The meat should fall apart easily with a fork; tougher cuts may need more time.",
        "Separately, cook the peeled potatoes (400 g) in salted water for 15-20 minutes until tender.",
        "Serve the stew with the potatoes and season with salt and pepper to taste.",
      ],
      "suggested_seasonings": [
        "sweet paprika",
        "caraway",
        "marjoram",
        "bay leaf",
      ],
    },
    "de": {
      "name": "Eintopf von Rindfleisch und Schweinefleisch",
      "description": "Ein dicker, wärmender, langsam kochender Eintopf.",
      "instructions": [
        "Würfeln Sie die Zwiebel (200 g) und schneiden Sie das Fleisch in Stücke über 2-3 cm.",
        "Erhitzen Sie das Öl in einem schweren Basistopf und braten Sie die Zwiebel für 3-4 Minuten bis weich.",
        "Fügen Sie das Fleisch hinzu und braten Sie es für 5-7 Minuten, bis jedes Stück auf allen Seiten gebräunt ist, was dem Eintopf einen tieferen Geschmack verleiht.",
        "Fügen Sie die süße Paprika (5 g) hinzu, rühren und braten Sie nur 1 Minute; Kochen länger kann es bitter machen.",
        "Gießen Sie die Passata (300 g) und genug Wasser, um das Fleisch fast zu bedecken, dann bedecken Sie den Topf.",
        "Reduzieren Sie die Hitze und kochen Sie für 25 Minuten. Das Fleisch sollte leicht mit einer Gabel auseinanderfallen; härtere Schnitte können mehr Zeit erfordern.",
        "Getrennt werden die geschälten Kartoffeln (400 g) in gesalzenem Wasser für 15-20 Minuten bis zur Ausschreibung gekocht.",
        "Servieren Sie den Eintopf mit den Kartoffeln und würzen Sie mit Salz und Pfeffer nach Geschmack.",
      ],
      "suggested_seasonings": [
        "Paprika, süß",
        "Kümmel",
        "Marjoram",
        "Lorbeerblatt",
      ],
    },
  },
  "b15211a9-db8a-50ce-963c-df2735cf92c3": {
    "source": {
      "name": "Chili con carne",
      "description": "Pikantne, sycące danie jednogarnkowe z fasolą.",
      "instructions": [
        "Cebulę (150 g) pokrój w drobną kostkę.",
        "Rozgrzej olej w garnku, podsmaż cebulę 3 minuty, aż zmięknie.",
        "Dodaj mięso mielone (400 g), rozdrabniaj łopatką i smaż 6-7 minut, aż się zrumieni i nie będzie różowe.",
        "Dodaj chili i kmin rzymski (5 g), smaż mieszając 1 minutę, aż przyprawy zapachną.",
        "Wlej pomidory krojone (400 g) i fasolę razem z zalewą z puszki, dokładnie wymieszaj.",
        "Zmniejsz ogień, przykryj i duś 20-25 minut, mieszając co jakiś czas, żeby nie przywarło.",
        "Spróbuj i dopraw solą, pieprzem lub dodatkowym chili według smaku. Podawaj gorące.",
      ],
      "suggested_seasonings": [
        "oregano",
        "papryka wędzona",
        "cynamon (szczypta)",
      ],
    },
    "en_GB": {
      "name": "Chilli con carne",
      "description": "A spicy, filling one-pot dish with beans.",
      "instructions": [
        "Finely dice the onion (150 g).",
        "Heat the oil in a saucepan and fry the onion for 3 minutes until soft.",
        "Add the mince (400 g), break it up with a spatula and fry for 6-7 minutes until browned and no longer pink.",
        "Add the chilli and cumin (5 g), then fry, stirring, for 1 minute until fragrant.",
        "Pour in the chopped tomatoes (400 g) and the beans with their tinned liquid, then stir thoroughly.",
        "Reduce the heat, cover and simmer for 20-25 minutes, stirring occasionally to prevent sticking.",
        "Taste and season with salt, pepper or extra chilli as desired. Serve hot.",
      ],
      "suggested_seasonings": [
        "oregano",
        "smoked paprika",
        "cinnamon (a pinch)",
      ],
    },
    "de": {
      "name": "Chilli con carne",
      "description": "Eine würzige, Eintopfschale mit Bohnen füllen.",
      "instructions": [
        "Die Zwiebel (150 g) fein würfeln.",
        "Erhitzen Sie das Öl in einem Topf und braten Sie die Zwiebel für 3 Minuten bis weich.",
        "Fügen Sie das Hackfleisch (400 g) hinzu, brechen Sie es mit einem Spatel auf und braten Sie es für 6-7 Minuten, bis es gebräunt und nicht mehr rosa ist.",
        "Fügen Sie die Chili und Kreuzkümmel (5 g), dann braten, Rühren, für 1 Minute, bis duftend.",
        "Gießen Sie die gehackten Tomaten (400 g) und die Bohnen mit ihrer verzinnten Flüssigkeit, dann rühren Sie gründlich.",
        "Reduzieren Sie die Hitze, decken Sie und kochen Sie für 20-25 Minuten, rühren Sie gelegentlich, um zu verhindern, dass Sie kleben.",
        "Probieren und würzen Sie mit Salz, Pfeffer oder extra Chili wie gewünscht.",
      ],
      "suggested_seasonings": [
        "Oregano",
        "geräucherte Paprika",
        "Zimt (eine Prise)",
      ],
    },
  },
