  "c863242f-75a0-5797-94f6-4d83699ff416": {
    "source": {
      "name": "Musli batoniki owsiane",
      "description": "Domowe batoniki zbożowe. świetne na wynos.",
      "instructions": [
        "Nagrzej piekarnik do 170°C, wyłóż małą blaszkę papierem do pieczenia.",
        "W rondelku na małym ogniu podgrzej miód (80 g) z masłem orzechowym (60 g), mieszając, aż się połączą w gładką masę (nie doprowadzaj do wrzenia).",
        "Zdejmij z ognia, dodaj płatki owsiane (200 g) i migdały, dokładnie wymieszaj.",
        "Przełóż masę na blachę, mocno dociśnij dłonią lub grzbietem łyżki, żeby była zbita i równa.",
        "Piecz 15-18 minut, aż brzegi zrobią się złociste.",
        "Wyjmij i zostaw do CAŁKOWITEGO ostygnięcia w formie (min. 30 minut) — krojenie na ciepło rozkruszy batoniki.",
        "Dopiero gdy całkiem ostygnie, pokrój na batoniki ostrym nożem.",
      ],
      "suggested_seasonings": ["cynamon", "wanilia"],
    },
    "en_GB": {
      "name": "Oat muesli bars",
      "description": "Homemade cereal bars — great for taking with you.",
      "instructions": [
        "Preheat the oven to 170°C and line a small baking tin with baking paper.",
        "Gently heat the honey (80 g) and peanut butter (60 g) in a small saucepan, stirring until smooth and combined. Do not bring to the boil.",
        "Remove from the heat, add the oats (200 g) and almonds, and mix thoroughly.",
        "Transfer the mixture to the tin and press firmly with your hand or the back of a spoon until compact and even.",
        "Bake for 15-18 minutes until the edges are golden.",
        "Remove and leave to cool COMPLETELY in the tin for at least 30 minutes. Cutting while warm will make the bars crumble.",
        "Only once completely cool, cut into bars with a sharp knife.",
      ],
      "suggested_seasonings": ["cinnamon", "vanilla"],
    },
    "de": {
      "name": "Hafermuscheln",
      "description":
          "Hausgemachte Müsliriegel - großartig, um sie mitzunehmen.",
      "instructions": [
        "Den Ofen auf 170°C vorheizen und eine kleine Backdose mit Backpapier auskleiden.",
        "Honig (80 g) und Erdnussbutter (60 g) sanft in einem kleinen Topf erhitzen, bis sie glatt und vereinigt sind; nicht zum Sieden bringen.",
        "Entfernen Sie aus der Hitze, fügen Sie den Hafer (200 g) und Mandeln hinzu und mischen Sie gründlich.",
        "Übertragen Sie die Mischung auf die Dose und drücken Sie fest mit der Hand oder der Rückseite eines Löffels, bis kompakt und gleichmäßig.",
        "Backen Sie für 15-18 Minuten, bis die Ränder golden sind.",
        "Die Stäbe werden mindestens 30 Minuten lang vollständig in der Dose abkühlen lassen.",
        "Nur einmal völlig kühl, mit einem scharfen Messer in Bars geschnitten.",
      ],
      "suggested_seasonings": ["Zimt", "Vanille"],
    },
  },
