    },
  },
  "de804b96-24c5-5e16-a2bb-a3f76aaf8392": {
    "source": {
      "name": "Sałatka z ciecierzycą i awokado",
      "description": "Sycąca, w pełni roślinna sałatka na kolację.",
      "instructions": [
        "Odsącz ciecierzycę (400 g) i wsyp do miski.",
        "Dodaj pokrojone w kostkę awokado (1 szt.) i pomidory (200 g).",
        "Skrop sokiem z cytryny (1 szt.) i oliwą z oliwek (20 g), dopraw solą.",
        "Delikatnie wymieszaj, żeby nie rozgnieść awokado.",
      ],
      "suggested_seasonings": ["kumin", "natka pietruszki"],
    },
    "en_GB": {
      "name": "Chickpea and avocado salad",
      "description": "A filling, fully plant-based salad for supper.",
      "instructions": [
        "Drain the chickpeas (400 g) and place in a bowl.",
        "Add the diced avocado (1 avocado) and tomatoes (200 g).",
        "Drizzle with lemon juice (1 lemon) and olive oil (20 g), then season with salt.",
        "Toss gently so you do not crush the avocado.",
      ],
      "suggested_seasonings": ["cumin", "parsley"],
    },
    "de": {
      "name": "Kichererbse und Avocado-Salat",
      "description":
          "Ein füllender, vollständig pflanzlicher Salat zum Abendessen.",
      "instructions": [
        "Die Kichererbsen (400 g) ablassen und in eine Schüssel geben.",
        "Fügen Sie die geschnittene Avocado (1 Avocado) und Tomaten (200 g) hinzu.",
        "Drizzle mit Zitronensaft (1 Zitrone) und Olivenöl (20 g), dann würzen Sie mit Salz.",
        "Werfen Sie sanft, damit Sie die Avocado nicht zerquetschen.",
      ],
      "suggested_seasonings": ["Kreuzkümmel", "Petersilie"],
    },
  },
  "cf6c18c6-bfc3-5b80-b676-2f47dc2ac88f": {
    "source": {
      "name": "Makaron z pomidorami i bazylią",
      "description": "Klasyczny, w pełni roślinny makaron pomodoro.",
      "instructions": [
        "Ugotuj makaron penne (200 g) w osolonej wodzie zgodnie z instrukcją na opakowaniu.",
        "Podsmaż przeciśnięty przez praskę czosnek (2 szt.) na oliwie z oliwek, aż zapachnie.",
        "Dodaj pomidory krojone (400 g), gotuj na małym ogniu 10-12 minut, aż sos zgęstnieje.",
        "Wmieszaj bazylię suszoną (2 g), odcedzony makaron dodaj do sosu i wymieszaj.",
      ],
      "suggested_seasonings": ["świeża bazylia", "płatki chili"],
    },
    "en_GB": {
      "name": "Tomato and basil pasta",
      "description": "Classic, fully plant-based pasta pomodoro.",
      "instructions": [
        "Cook the penne (200 g) in salted water according to the packet instructions.",
        "Fry the crushed garlic (2 cloves) in olive oil until fragrant.",
        "Add the chopped tomatoes (400 g) and simmer over a low heat for 10-12 minutes until the sauce thickens.",
        "Stir in the dried basil (2 g), then add the drained pasta to the sauce and mix.",
      ],
      "suggested_seasonings": ["fresh basil", "chilli flakes"],
    },
    "de": {
      "name": "Tomaten- und Basilikum-Teigwaren",
      "description": "Klassische, vollständig pflanzliche Pasta pomodoro.",
      "instructions": [
        "Kochen Sie den Penne (200 g) in gesalzenem Wasser gemäß den Packungsanweisungen.",
        "Braten Sie den zerkleinerten Knoblauch (2 Nelken) in Olivenöl bis zum Duft.",
        "Fügen Sie die zerkleinerten Tomaten (400 g) hinzu und kochen Sie über eine niedrige Hitze für 10-12 Minuten, bis sich die Sauce verdickt.",
        "Rühren Sie im getrockneten Basilikum (2 g), fügen Sie dann die abgelassene Pasta zur Soße hinzu und mischen Sie sie.",
      ],
      "suggested_seasonings": ["Frisches Basilikum", "Chili-Flocken"],
    },
  },
  "fef808dd-f283-5b27-9c0a-52ecff35858f": {
    "source": {
      "name": "Kasza gryczana z warzywami",
      "description": "Sycąca, w pełni roślinna kasza z warzywami na patelni.",
      "instructions": [
        "Ugotuj kaszę gryczaną (200 g) zgodnie z instrukcją na opakowaniu.",
        "Podsmaż na oliwie pokrojoną w kostkę cukinię (1 szt.), paprykę (1 szt.) i cebulę (100 g).",
        "Smaż 8-10 minut, aż warzywa zmiękną.",
        "Wymieszaj z ugotowaną kaszą, dopraw solą i pieprzem.",
      ],
      "suggested_seasonings": ["papryka wędzona", "majeranek"],
    },
    "en_GB": {
      "name": "Buckwheat with vegetables",
      "description":
          "A filling, fully plant-based dish of buckwheat and pan-fried vegetables.",
      "instructions": [
        "Cook the buckwheat (200 g) according to the packet instructions.",
        "Fry the diced courgette (1 courgette), pepper (1 pepper) and onion (100 g) in olive oil.",
        "Fry for 8-10 minutes until the vegetables soften.",
        "Mix with the cooked buckwheat and season with salt and pepper.",
      ],
      "suggested_seasonings": ["smoked paprika", "marjoram"],
    },
    "de": {
      "name": "Buchweizen mit Gemüse",
      "description":
          "Ein füllendes, vollständig pflanzliches Gericht mit Buchweizen und gebratenem Gemüse.",
      "instructions": [
        "Kochen Sie den Buchweizen (200 g) gemäß den Packungsanweisungen.",
        "Frittieren Sie die gewürfelten Zucchini (1 Zucchini), Pfeffer (1 Pfeffer) und Zwiebeln (100 g) in Olivenöl.",
        "Braten Sie für 8-10 Minuten, bis das Gemüse weich wird.",
        "Mischen Sie mit dem gekochten Buchweizen und Saison mit Salz und Pfeffer.",
      ],
      "suggested_seasonings": ["geräucherte Paprika", "Marjoram"],
    },
  },
  "644406b6-bee2-5da4-b050-1efd1ff1da18": {
    "source": {
      "name": "Awokado z jajkiem sadzonym",
      "description": "Niskowęglowodanowe śniadanie bez pieczywa.",
      "instructions": [
        "Przekrój awokado (1 szt.) na pół, usuń pestkę.",
        "Rozgrzej masło (10 g) na patelni, usmaż jajka (2 szt.) sadzone.",
        "Ułóż jajka na połówkach awokado, dopraw solą i pieprzem.",
      ],
      "suggested_seasonings": ["płatki chili", "szczypiorek"],
    },
    "en_GB": {
      "name": "Avocado with fried eggs",
      "description": "A low-carbohydrate breakfast without bread.",
      "instructions": [
        "Halve the avocado (1 avocado) and remove the stone.",
        "Heat the butter (10 g) in a frying pan and fry the eggs (2 eggs).",
        "Place the eggs on the avocado halves and season with salt and pepper.",
      ],
      "suggested_seasonings": ["chilli flakes", "chives"],
    },
    "de": {
      "name": "Avocado mit gebratenen Eiern",
      "description": "Ein kohlenhydratarmes Frühstück ohne Brot.",
      "instructions": [
        "Halbieren Sie die Avocado (1 Avocado) und entfernen Sie den Stein.",
        "Erhitzen Sie die Butter (10 g) in einer Bratpfanne und braten Sie die Eier (2 Eier).",
        "Legen Sie die Eier auf die Avocado-Hälften und Saison mit Salz und Pfeffer.",
      ],
      "suggested_seasonings": ["Chili-Flocken", "Schnittlauch"],
    },
  },
  "8403654e-b581-58f0-a9b6-e1410e1f7b1f": {
    "source": {
      "name": "Kurczak z masłem ziołowym i brokułem",
      "description": "Niskowęglowodanowy, wysokobiałkowy obiad.",
      "instructions": [
        "Dopraw pierś z kurczaka (350 g) solą i pieprzem, usmaż na oliwie z obu stron do złocistości i miękkości (ok. 6-7 minut na stronę).",
        "Ugotuj brokuł (1 szt.) na parze albo w wodzie przez 5-6 minut.",
        "Rozpuść masło (20 g) z przeciśniętym czosnkiem (2 szt.), polej nim kurczaka i brokuł przed podaniem.",
      ],
      "suggested_seasonings": ["tymianek", "rozmaryn"],
    },
    "en_GB": {
      "name": "Chicken with herb butter and broccoli",
      "description": "A low-carbohydrate, high-protein lunch.",
      "instructions": [
        "Season the chicken breast (350 g) with salt and pepper, then fry in olive oil on both sides until golden and tender, about 6-7 minutes per side.",
        "Steam or boil the broccoli (1 broccoli) for 5-6 minutes.",
        "Melt the butter (20 g) with the crushed garlic (2 cloves) and pour over the chicken and broccoli before serving.",
      ],
      "suggested_seasonings": ["thyme", "rosemary"],
    },
    "de": {
      "name": "Hähnchen mit Kräuterbutter und Brokkoli",
      "description": "Ein kohlenhydratarmes, proteinreiches Mittagessen.",
      "instructions": [
        "Die Hähnchenbrust (350 g) mit Salz und Pfeffer würzen, dann in Olivenöl auf beiden Seiten braten, bis golden und zart, etwa 6-7 Minuten pro Seite.",
        "Dampf oder kochen Sie den Brokkoli (1 Brokkoli) für 5-6 Minuten.",
        "Schmelzen Sie die Butter (20 g) mit dem zerkleinerten Knoblauch (2 Nelken) und gießen Sie über das Huhn und Brokkoli vor dem Servieren.",
      ],
      "suggested_seasonings": ["Thymian", "Rosmarin"],
    },
  },
  "9f1da5ac-f8f8-5411-a931-c62e85fee34d": {
    "source": {
      "name": "Jajka na twardo",
      "description":
          "Najprostsza, wysokobiałkowa przekąska niskowęglowodanowa.",
      "instructions": [
        "Włóż jajka (3 szt.) do rondelka, zalej zimną wodą tak, żeby je przykryła.",
        "Zagotuj, potem gotuj na małym ogniu 8-9 minut.",
        "Przelej zimną wodą i obierz ze skorupek, dopraw solą przed jedzeniem.",
      ],
      "suggested_seasonings": ["pieprz czarny", "szczypiorek"],
    },
    "en_GB": {
      "name": "Hard-boiled eggs",
      "description": "The simplest high-protein, low-carbohydrate snack.",
      "instructions": [
        "Place the eggs (3 eggs) in a small saucepan and cover with cold water.",
        "Bring to the boil, then simmer over a low heat for 8-9 minutes.",
        "Rinse under cold water, peel and season with salt before eating.",
      ],
      "suggested_seasonings": ["black pepper", "chives"],
    },
    "de": {
      "name": "Hartgekochte Eier",
      "description": "Der einfachste proteinreiche, kohlenhydratarme Snack.",
      "instructions": [
        "Legen Sie die Eier (3 Eier) in einen kleinen Topf und decken Sie mit kaltem Wasser.",
        "Bringen Sie zum Kochen, dann kochen Sie über eine niedrige Hitze für 8-9 Minuten.",
        "Spülen Sie unter kaltem Wasser, schälen und würzen Sie vor dem Essen mit Salz.",
      ],
      "suggested_seasonings": ["Schwarzer Pfeffer", "Schnittlauch"],
    },
  },
  "bd49465a-6329-5ae2-9d30-789658bb2b8e": {
    "source": {
      "name": "Oliwki z serem feta",
      "description": "Śródziemnomorska, niskowęglowodanowa przekąska.",
      "instructions": [
        "Wymieszaj oliwki czarne (50 g) z pokrojonym w kostkę serem feta (50 g).",
        "Skrop oliwą z oliwek (10 g) i podawaj.",
      ],
      "suggested_seasonings": ["oregano", "pieprz czarny"],
    },
    "en_GB": {
      "name": "Olives with feta",
      "description": "A Mediterranean, low-carbohydrate snack.",
      "instructions": [
        "Mix the black olives (50 g) with the diced feta (50 g).",
        "Drizzle with olive oil (10 g) and serve.",
      ],
      "suggested_seasonings": ["oregano", "black pepper"],
    },
    "de": {
      "name": "Oliven mit Feta",
      "description": "Ein mediterraner, kohlenhydratarmer Snack.",
      "instructions": [
        "Mischen Sie die schwarzen Oliven (50 g) mit dem gewürfelten Feta (50 g).",
        "Drizzle mit Olivenöl (10 g) und dienen.",
      ],
      "suggested_seasonings": ["Oregano", "Schwarzer Pfeffer"],
    },
  },
  "9ce542e4-202d-5772-ba43-0a43baff60d5": {
    "source": {
      "name": "Twaróg z miodem",
      "description": "Prosta, wysokobiałkowa przekąska na słodko.",
      "instructions": [
        "Wyłóż twaróg półtłusty (150 g) na talerzyk.",
        "Polej miodem (20 g) i podawaj.",
      ],
      "suggested_seasonings": ["orzechy", "cynamon"],
    },
    "en_GB": {
      "name": "Quark with honey",
      "description": "A simple, high-protein sweet snack.",
      "instructions": [
        "Place the semi-fat quark (150 g) on a small plate.",
        "Drizzle with honey (20 g) and serve.",
      ],
      "suggested_seasonings": ["nuts", "cinnamon"],
    },
    "de": {
      "name": "Quark mit Honig",
      "description": "Ein einfacher, proteinreicher süßer Snack.",
      "instructions": [
        "Legen Sie den Halbfettquark (150 g) auf eine kleine Platte.",
        "Drizzle mit Honig (20 g) und dienen.",
      ],
      "suggested_seasonings": ["Muttern", "Zimt"],
    },
  },
  "762e2a80-f4a7-52f4-82a2-8b0db789bd90": {
    "source": {
      "name": "Szynka z serem",
      "description": "Szybka, wysokobiałkowa przekąska bez gotowania.",
      "instructions": [
        "Ułóż na talerzu plastry szynki konserwowej (80 g) i sera żółtego gouda (50 g).",
      ],
      "suggested_seasonings": ["musztarda", "rzeżucha"],
    },
    "en_GB": {
      "name": "Ham with cheese",
      "description": "A quick, high-protein snack with no cooking.",
      "instructions": [
        "Arrange the cooked ham slices (80 g) and Gouda (50 g) on a plate.",
      ],
      "suggested_seasonings": ["mustard", "cress"],
    },
    "de": {
      "name": "Schinken mit Käse",
      "description": "Ein schneller, proteinreicher Snack ohne Kochen.",
      "instructions": [
        "Ordne die gekochten Schinkenscheiben (80 g) und Gouda (50 g) auf einem Teller an.",
      ],
      "suggested_seasonings": ["Senf", "Kresse"],
    },
  },
  "e8e9eceb-ff92-54cc-96ce-2b92250af818": {
    "source": {
      "name": "Jogurt z orzechami",
      "description": "Prosta, wysokobiałkowa przekąska.",
      "instructions": [
        "Wyłóż jogurt naturalny (200 g) do miseczki.",
        "Posyp orzechami włoskimi (20 g) i podawaj.",
      ],
      "suggested_seasonings": ["miód", "cynamon"],
    },
    "en_GB": {
      "name": "Yoghurt with nuts",
      "description": "A simple, high-protein snack.",
      "instructions": [
        "Spoon the natural yoghurt (200 g) into a bowl.",
        "Sprinkle with walnuts (20 g) and serve.",
      ],
      "suggested_seasonings": ["honey", "cinnamon"],
    },
    "de": {
      "name": "Joghurt mit Nüssen",
      "description": "Ein einfacher, proteinreicher Snack.",
      "instructions": [
        "Löffel den natürlichen Joghurt (200 g) in eine Schüssel.",
        "Streuen Sie mit Walnüssen (20 g) und dienen.",
      ],
      "suggested_seasonings": ["Honig", "Zimt"],
    },
  },
  "c736ce38-9ced-50a6-acbb-52c827c2094f": {
    "source": {
      "name": "Sałatka z tuńczyka i ogórkiem",
      "description": "Lekka, wysokobiałkowa przekąska bez gotowania.",
      "instructions": [
        "Odsącz tuńczyka (100 g) i wymieszaj z pokrojonym w kostkę ogórkiem (1 szt.).",
        "Skrop oliwą z oliwek (10 g), dopraw solą i pieprzem.",
      ],
      "suggested_seasonings": ["koperek", "cytryna"],
    },
    "en_GB": {
      "name": "Tuna and cucumber salad",
      "description": "A light, high-protein snack with no cooking.",
      "instructions": [
        "Drain the tuna (100 g) and mix with the diced cucumber (1 cucumber).",
        "Drizzle with olive oil (10 g) and season with salt and pepper.",
      ],
      "suggested_seasonings": ["dill", "lemon"],
    },
    "de": {
      "name": "Thunfisch- und Gurkensalat",
      "description": "Ein leichter, proteinreicher Snack ohne Kochen.",
      "instructions": [
        "Den Thunfisch (100 g) ablassen und mit der Gurke (1 Gurke) mischen.",
        "Drizzle mit Olivenöl (10 g) und Saison mit Salz und Pfeffer.",
      ],
      "suggested_seasonings": ["Dill", "Zitrone"],
    },
  },
  "ccf5dda8-d37d-5ec3-b06a-dca7d9b36702": {
    "source": {
      "name": "Mandarynkowe skrzydełka z airfryera",
      "description": "Soczyste skrzydełka w cytrusowej glazurze z tamari.",
      "instructions": [
        "Wyciśnij sok z mandarynek, połącz z tamari, miodem i startym czosnkiem.",
        "Wymieszaj skrzydełka z połową glazury i ułóż je pojedynczą warstwą w koszu.",
        "Piecz 24 minuty w 180°C, obracając po 12 minutach.",
        "Posmaruj pozostałą glazurą i dopiecz 2 minuty. Sprawdź, czy mięso jest całkowicie upieczone.",
      ],
      "suggested_seasonings": ["imbir", "płatki chili"],
    },
    "en_GB": {
      "name": "Air fryer mandarin chicken wings",
      "description": "Juicy wings in a citrus and tamari glaze.",
      "instructions": [
        "Squeeze the mandarins and combine the juice with tamari, honey and grated garlic.",
        "Toss the wings with half the glaze and arrange in a single layer in the basket.",
        "Cook for 24 minutes at 180°C, turning after 12 minutes.",
        "Brush with the remaining glaze and cook for 2 more minutes. Check that the meat is fully cooked.",
      ],
      "suggested_seasonings": ["ginger", "chilli flakes"],
    },
    "de": {
      "name": "Air Friteuse Mandarin Chicken Wings",
      "description": "Juicy Flügel in einer Zitrus- und Tamariglasur.",
      "instructions": [
        "Drücken Sie die Mandarinen und kombinieren Sie den Saft mit Tamari, Honig und geriebenem Knoblauch.",
        "Werfen Sie die Flügel mit der Hälfte der Glasur und ordnen Sie in einer einzigen Schicht im Korb an.",
        "Kochen Sie für 24 Minuten bei 180 ° C, Drehen nach 12 Minuten.",
        "Mit der restlichen Glasur bürsten und weitere 2 Minuten kochen.",
      ],
      "suggested_seasonings": ["Ingwer", "Chili-Flocken"],
    },
  },
  "289b9403-45b9-5819-8826-77a8ef18c9d3": {
    "source": {
      "name": "Łosoś teriyaki z fasolką z airfryera",
      "description":
          "Łosoś i świeża fasolka przygotowane razem w jednym koszu.",
      "instructions": [
        "Posmaruj łososia sosem teriyaki, a fasolkę wymieszaj z oliwą.",
        "Włóż fasolkę do kosza i piecz 3 minuty w 190°C.",
        "Dodaj łososia i piecz całość kolejne 8 minut, aż ryba łatwo rozdzieli się widelcem.",
        "Posyp sezamem i podaj z limonką.",
      ],
      "suggested_seasonings": ["pieprz", "imbir"],
    },
    "en_GB": {
      "name": "Air fryer teriyaki salmon with green beans",
      "description":
          "Salmon and fresh green beans cooked together in one basket.",
      "instructions": [
        "Brush the salmon with teriyaki sauce and toss the green beans with olive oil.",
        "Place the green beans in the basket and cook for 3 minutes at 190°C.",
        "Add the salmon and cook everything for another 8 minutes until the fish flakes easily with a fork.",
        "Sprinkle with sesame seeds and serve with lime.",
      ],
      "suggested_seasonings": ["pepper", "ginger"],
    },
    "de": {
      "name": "Air Friteus teriyaki Lachs mit grünen Bohnen",
      "description":
          "Lachs und frische grüne Bohnen werden zusammen in einem Korb gekocht.",
      "instructions": [
        "Den Lachs mit Teriyaki-Sauce bürsten und die grünen Bohnen mit Olivenöl werfen.",
        "Legen Sie die grünen Bohnen in den Korb und kochen Sie für 3 Minuten bei 190 ° C.",
        "Fügen Sie den Lachs hinzu und kochen Sie alles weitere 8 Minuten, bis der Fisch mit einer Gabel leicht abblättert.",
        "Streuen Sie mit Sesamsamen und dienen Sie mit Limette.",
      ],
      "suggested_seasonings": ["Pfeffer", "Ingwer"],
    },
  },
  "f7773aa5-4ed9-548b-898e-bd1f08f83e3e": {
    "source": {
      "name": "Paluszki z dorsza w panko z airfryera",
      "description": "Domowe paluszki rybne z chrupiącą panierką panko.",
      "instructions": [
        "Pokrój dorsza w grube paski i dokładnie osusz.",
        "Obtocz kawałki kolejno w mące, roztrzepanym jajku i panko.",
        "Spryskaj oliwą i piecz 10–12 minut w 190°C, obracając w połowie.",
        "Podaj z jogurtem wymieszanym z sokiem z cytryny.",
      ],
      "suggested_seasonings": ["papryka słodka", "pieprz"],
    },
    "en_GB": {
      "name": "Air fryer panko cod fingers",
      "description": "Homemade fish fingers in a crisp panko coating.",
      "instructions": [
        "Cut the cod into thick strips and pat thoroughly dry.",
        "Coat the pieces in flour, beaten egg and then panko.",
        "Spray with olive oil and cook for 10–12 minutes at 190°C, turning halfway through.",
        "Serve with yoghurt mixed with lemon juice.",
      ],
      "suggested_seasonings": ["sweet paprika", "pepper"],
    },
    "de": {
      "name": "Air Friteusenfischer",
      "description":
          "Hausgemachte Fischfinger in einer knackigen Panko-Beschichtung.",
      "instructions": [
        "Schneiden Sie den Kabeljau in dicke Streifen und trocknen Sie gründlich.",
        "Beschichten Sie die Stücke in Mehl, geschlagenes Ei und dann Panko.",
        "Spray mit Olivenöl und Kochen für 10-12 Minuten bei 190 ° C, Drehen auf halbem Weg durch.",
        "Servieren Sie mit Joghurt gemischt mit Zitronensaft.",
      ],
      "suggested_seasonings": ["Paprika, süß", "Pfeffer"],
    },
  },
  "abea3214-ff82-599d-8445-51771f7078f9": {
    "source": {
      "name": "Krewetki kokosowe z airfryera",
      "description":
          "Krewetki w lekkiej panierce kokosowej z sosem sweet chili.",
      "instructions": [
        "Osusz krewetki i zanurz je w roztrzepanym jajku.",
        "Wymieszaj panko z wiórkami kokosowymi i obtocz krewetki.",
        "Ułóż bez nakładania na siebie i piecz 7–8 minut w 190°C.",
        "Podaj od razu z sosem sweet chili i limonką.",
      ],
      "suggested_seasonings": ["sól", "pieprz"],
    },
    "en_GB": {
      "name": "Air fryer coconut prawns",
      "description":
          "Prawns in a light coconut coating with sweet chilli sauce.",
      "instructions": [
        "Pat the prawns dry and dip into beaten egg.",
        "Mix the panko with desiccated coconut and coat the prawns.",
        "Arrange without overlapping and cook for 7–8 minutes at 190°C.",
        "Serve immediately with sweet chilli sauce and lime.",
      ],
      "suggested_seasonings": ["salt", "pepper"],
