  "0bc945f9-8342-5d84-a3b0-972485b9c1f1": {
    "source": {
      "name": "Frytki z polenty z sosem marinara",
      "description":
          "Złociste paluszki polenty do maczania w sosie pomidorowym.",
      "instructions": [
        "Ugotuj polentę w bulionie, dodaj parmezan i rozsmaruj na grubość 2 cm.",
        "Po ostudzeniu pokrój ją w słupki i posmaruj oliwą.",
        "Piecz 14–16 minut w 200°C, obracając po 8 minutach.",
        "Podaj z podgrzanym sosem marinara.",
      ],
      "suggested_seasonings": ["oregano", "pieprz"],
    },
    "en_GB": {
      "name": "Polenta fries with marinara sauce",
      "description": "Golden polenta sticks for dipping in tomato sauce.",
      "instructions": [
        "Cook the polenta in stock, add Parmesan and spread out to a thickness of 2 cm.",
        "Once cool, cut into sticks and brush with olive oil.",
        "Cook for 14–16 minutes at 200°C, turning after 8 minutes.",
        "Serve with warmed marinara sauce.",
      ],
      "suggested_seasonings": ["oregano", "pepper"],
    },
    "de": {
      "name": "Pommes frites mit Marinara-Sauce",
      "description": "Goldene Polenta-Stäbchen zum Tauchen in Tomatensauce.",
      "instructions": [
        "Kochen Sie die Polenta auf Lager, fügen Sie Parmesan hinzu und verteilen Sie sich auf eine Dicke von 2 cm.",
        "Einmal abkühlen, in Stäbchen schneiden und mit Olivenöl bürsten.",
        "Kochen für 14-16 Minuten bei 200°C, Drehen nach 8 Minuten.",
        "Servieren Sie mit erwärmter Marinara-Sauce.",
      ],
      "suggested_seasonings": ["Oregano", "Pfeffer"],
    },
  },
  "5de972f2-183c-5156-805f-746ce414b694": {
    "source": {
      "name": "Brokułowe kąski z cheddarem",
      "description": "Miękkie w środku, rumiane kąski z brokułu i sera.",
      "instructions": [
        "Krótko obgotuj brokuł, ostudź i drobno posiekaj.",
        "Połącz z cheddarem, jajkiem i bułką tartą.",
        "Uformuj małe kąski i ułóż je w koszu.",
        "Piecz 10–12 minut w 190°C, obracając raz.",
      ],
      "suggested_seasonings": ["czosnek granulowany", "pieprz"],
    },
    "en_GB": {
      "name": "Broccoli and Cheddar bites",
      "description": "Golden broccoli and cheese bites with soft centres.",
      "instructions": [
        "Briefly blanch the broccoli, cool and finely chop.",
        "Combine with Cheddar, egg and breadcrumbs.",
        "Shape into small bites and arrange in the basket.",
        "Cook for 10–12 minutes at 190°C, turning once.",
      ],
      "suggested_seasonings": ["garlic granules", "pepper"],
    },
    "de": {
      "name": "Broccoli und Cheddar-Bisse",
      "description": "Goldener Brokkoli und Käsebisse mit weichen Zentren.",
      "instructions": [
        "Kurz blanch den Brokkoli, kühl und fein gehackt.",
        "Kombinieren Sie mit Cheddar, Eiern und Semmelbrösel.",
        "Gestalten Sie sich in kleine Bisse und ordnen Sie sich im Korb an.",
        "Kochen Sie für 10-12 Minuten bei 190°C und drehen Sie sich einmal.",
      ],
      "suggested_seasonings": ["Knoblauchgranulat", "Pfeffer"],
    },
  },
  "1a0e4f77-aced-56f9-b6c3-77d9892074c8": {
    "source": {
      "name": "Wędzona kukurydza z limonką z airfryera",
      "description": "Kolby kukurydzy z limonką i dymnym aromatem papryki.",
      "instructions": [
        "Posmaruj kolby oliwą i oprósz wędzoną papryką.",
        "Piecz 12–13 minut w 195°C, obracając co 4 minuty.",
        "Posmaruj jogurtem, skrop limonką i posyp kolendrą.",
      ],
      "suggested_seasonings": ["papryka wędzona", "sól"],
    },
    "en_GB": {
      "name": "Air fryer smoky corn with lime",
      "description": "Corn on the cob with lime and smoky paprika.",
      "instructions": [
        "Brush the cobs with olive oil and dust with smoked paprika.",
        "Cook for 12–13 minutes at 195°C, turning every 4 minutes.",
        "Spread with yoghurt, drizzle with lime juice and sprinkle with coriander.",
      ],
      "suggested_seasonings": ["smoked paprika", "salt"],
    },
    "de": {
      "name": "Luftfritteuse rauchiger Mais mit Limette",
      "description": "Mais auf dem Kolben mit Limette und rauchige Paprika.",
      "instructions": [
        "Bürsten Sie die Kolben mit Olivenöl und Staub mit geräucherter Paprika.",
        "Kochen Sie für 12-13 Minuten bei 195°C und drehen Sie alle 4 Minuten.",
        "Verbreiten Sie mit Joghurt, Nieselregen mit Limettensaft und streuen Sie mit Koriander.",
      ],
      "suggested_seasonings": ["geräucherte Paprika", "Salz"],
    },
  },
  "be2451d0-791c-5750-a44f-7b60f50740a9": {
    "source": {
      "name": "Jabłkowe crumble z airfryera",
      "description": "Ciepłe jabłka pod kruszonką z płatków i orzechów.",
      "instructions": [
        "Pokrój jabłka i wymieszaj je z cynamonem oraz sokiem z cytryny.",
        "Przełóż do niewielkiego naczynia pasującego do kosza.",
        "Rozetrzyj płatki, mąkę, masło i orzechy, następnie przykryj jabłka.",
        "Piecz 15–16 minut w 175°C do zrumienienia kruszonki.",
      ],
      "suggested_seasonings": ["cynamon", "wanilia"],
    },
    "en_GB": {
      "name": "Air fryer apple crumble",
      "description": "Warm apples under an oat and nut crumble topping.",
      "instructions": [
        "Chop the apples and toss with cinnamon and lemon juice.",
        "Transfer to a small dish that fits in the basket.",
        "Rub together the oats, flour, butter and nuts, then use to cover the apples.",
        "Cook for 15–16 minutes at 175°C until the crumble is golden.",
      ],
      "suggested_seasonings": ["cinnamon", "vanilla"],
    },
    "de": {
      "name": "Air Friteuse Apfel bröckelt",
      "description": "Warme Äpfel unter Hafer und Nuss zerbröckeln.",
      "instructions": [
        "Hacken Sie die Äpfel und werfen Sie mit Zimt und Zitronensaft.",
        "Übertragen Sie auf eine kleine Schüssel, die in den Korb passt.",
        "Reiben Sie den Hafer, Mehl, Butter und Nüsse zusammen und verwenden Sie dann die Äpfel.",
        "Kochen Sie für 15-16 Minuten bei 175°C, bis der Bröckel golden ist.",
      ],
      "suggested_seasonings": ["Zimt", "Vanille"],
    },
  },
  "6bfb9318-302b-5351-83fc-4cae424081b9": {
    "source": {
      "name": "Gruszki z serem pleśniowym i pekanami",
      "description":
          "Pieczone gruszki z kremowym serem i chrupiącymi orzechami.",
      "instructions": [
        "Przekrój gruszki na pół i usuń gniazda nasienne.",
        "W zagłębienia włóż ser pleśniowy i posiekane orzechy.",
        "Piecz 8–10 minut w 180°C, aż gruszki zmiękną.",
        "Skrop miodem tuż przed podaniem.",
      ],
      "suggested_seasonings": ["tymianek", "pieprz"],
    },
    "en_GB": {
      "name": "Pears with mould-ripened cheese and pecans",
      "description": "Baked pears with creamy cheese and crunchy nuts.",
      "instructions": [
        "Halve and core the pears.",
        "Fill the hollows with mould-ripened cheese and chopped nuts.",
        "Cook for 8–10 minutes at 180°C until the pears soften.",
        "Drizzle with honey just before serving.",
      ],
      "suggested_seasonings": ["thyme", "pepper"],
    },
    "de": {
      "name": "Birnen mit schimmelgereiftem Käse und Pekannüssen",
      "description": "Backbirnen mit cremigem Käse und knusprigen Nüssen.",
      "instructions": [
        "Halbieren und Kernen der Birnen.",
        "Die Mulden werden mit schimmelgereiftem Käse und zerkleinerten Nüssen gefüllt.",
        "Kochen Sie für 8-10 Minuten bei 180°C, bis die Birnen weich werden.",
        "Drizzle mit Honig kurz vor dem Servieren.",
      ],
      "suggested_seasonings": ["Thymian", "Pfeffer"],
    },
  },
  "15e3ae67-96e9-56f4-b2ce-fb3ed3dd02df": {
    "source": {
      "name": "Pomarańczowe serniczki ze skyru",
      "description": "Małe serniczki ze skyru pachnące świeżą pomarańczą.",
      "instructions": [
        "Wymieszaj skyr z jajkiem, budyniem, miodem i skórką z pomarańczy.",
        "Rozlej masę do czterech silikonowych foremek.",
        "Piecz 12–14 minut w 160°C, aż środek będzie lekko sprężysty.",
        "Ostudź i schłodź przed wyjęciem z foremek.",
      ],
      "suggested_seasonings": ["wanilia", "kardamon"],
    },
    "en_GB": {
      "name": "Mini orange skyr cheesecakes",
      "description": "Small skyr cheesecakes scented with fresh orange.",
      "instructions": [
        "Mix the skyr with egg, vanilla pudding powder, honey and orange zest.",
        "Divide the mixture between four silicone moulds.",
        "Cook for 12–14 minutes at 160°C until the centres are slightly springy.",
        "Leave to cool, then chill before removing from the moulds.",
      ],
      "suggested_seasonings": ["vanilla", "cardamom"],
    },
    "de": {
      "name": "Mini-Orange-Skyr-Käsekuchen",
      "description": "Kleine Skyr Käsekuchen duftend mit frischer Orange.",
      "instructions": [
        "Mischen Sie den Skyr mit Ei, Vanillepuddingpulver, Honig und Orangenzeste.",
        "Teilen Sie die Mischung auf vier Silikonformen.",
        "Kochen Sie für 12-14 Minuten bei 160°C, bis die Zentren leicht federnd sind.",
        "Man lässt abkühlen und kühlt dann ab, bevor man die Schimmel entformt.",
      ],
      "suggested_seasonings": ["Vanille", "Kardamom"],
    },
  },
  "e013e9f4-1519-51ef-9b75-2539ee4a4df7": {
    "source": {
      "name": "Bananowo-kakaowe muffinki z airfryera",
      "description":
          "Wilgotne muffinki słodzone dojrzałym bananem i daktylami.",
      "instructions": [
        "Rozgnieć banany i połącz z jajkiem oraz drobno pokrojonymi daktylami.",
        "Dodaj mąkę, kakao i proszek do pieczenia, mieszając tylko do połączenia.",
        "Napełnij silikonowe foremki do dwóch trzecich wysokości.",
        "Piecz 12–14 minut w 165°C; sprawdź patyczkiem przed wyjęciem.",
      ],
      "suggested_seasonings": ["cynamon", "wanilia"],
    },
    "en_GB": {
      "name": "Air fryer banana and cocoa muffins",
      "description": "Moist muffins sweetened with ripe banana and dates.",
      "instructions": [
        "Mash the bananas and combine with the egg and finely chopped dates.",
        "Add the flour, cocoa and baking powder, stirring just until combined.",
        "Fill the silicone moulds two-thirds full.",
        "Cook for 12–14 minutes at 165°C; check with a skewer before removing.",
      ],
      "suggested_seasonings": ["cinnamon", "vanilla"],
    },
    "de": {
      "name": "Air Friteus Bananen- und Kakaomuffins",
      "description": "Feuchte Muffins gesüßt mit reifen Bananen und Datteln.",
      "instructions": [
        "Mash die Bananen und kombinieren mit dem Ei und fein gehackten Datteln.",
        "Fügen Sie das Mehl, Kakao und Backpulver hinzu und rühren Sie nur bis zur Kombination.",
        "Füllen Sie die Silikonformen zu zwei Dritteln.",
        "Kochen Sie für 12-14 Minuten bei 165°C; überprüfen Sie mit einem Spieß vor dem Entfernen.",
      ],
      "suggested_seasonings": ["Zimt", "Vanille"],
    },
  },
  "e5b69f8c-346f-5227-90a3-2433a7ea3708": {
    "source": {
      "name": "Brzoskwiniowe rożki z ciasta francuskiego",
      "description": "Kruche rożki z brzoskwinią, migdałami i wanilią.",
      "instructions": [
        "Pokrój ciasto na sześć kwadratów, a brzoskwinie w małą kostkę.",
        "Na każdym kawałku ułóż owoce i odrobinę mąki migdałowej.",
        "Złóż po przekątnej, mocno dociśnij brzegi i posmaruj jajkiem.",
        "Piecz partiami 10–12 minut w 180°C do wyraźnego zrumienienia.",
      ],
      "suggested_seasonings": ["wanilia", "cynamon"],
    },
    "en_GB": {
      "name": "Peach puff pastry turnovers",
      "description": "Flaky turnovers with peach, almonds and vanilla.",
      "instructions": [
        "Cut the pastry into six squares and finely dice the peaches.",
        "Place fruit and a little almond flour on each piece.",
        "Fold diagonally, press the edges firmly and brush with egg.",
        "Cook in batches for 10–12 minutes at 180°C until well browned.",
      ],
      "suggested_seasonings": ["vanilla", "cinnamon"],
    },
    "de": {
      "name": "Umschlag von Pfirsichpuffgebäck",
      "description": "Flockige Umsätze mit Pfirsichen, Mandeln und Vanille.",
      "instructions": [
        "Schneiden Sie das Gebäck in sechs Quadrate und würfeln Sie die Pfirsiche fein.",
        "Legen Sie Obst und ein wenig Mandelmehl auf jedes Stück.",
        "Falten Sie diagonal, drücken Sie die Kanten fest und bürsten Sie mit Ei.",
        "Kochen Sie in Chargen für 10-12 Minuten bei 180 ° C, bis gut gebräunt.",
      ],
      "suggested_seasonings": ["Vanille", "Zimt"],
    },
  },
  "9b700d52-311a-564a-86b2-3598e27ef50c": {
    "source": {
      "name": "Sałatka z indykiem, dynią i pęczakiem",
      "description":
          "Jesienna propozycja: sałatka z indykiem, dynią i pęczakiem. Opracowanie na podstawie Centrum Respo. Wartości odżywcze są orientacyjne.",
      "instructions": [
        "Ugotuj pęczak zgodnie z opakowaniem. Dynię oczyść i pokrój, a indyka podziel na kawałki.",
        "Wymieszaj dynię i indyka z oliwą, papryką wędzoną, czosnkiem, kuminem, solą i pieprzem. Piecz w 200°C przez 18–20 minut; sprawdź, czy mięso jest całkowicie upieczone.",
        "Połącz masło orzechowe, sos sojowy, sok z cytryny, miód i wodę. Słonecznik podpraż na suchej patelni.",
        "Ułóż kaszę, dynię i indyka w misce. Dodaj sos, słonecznik oraz posiekaną natkę.",
      ],
      "suggested_seasonings": [],
    },
    "en_GB": {
      "name": "Warm turkey, pumpkin and barley salad",
      "description":
          "An autumn dish: warm turkey, pumpkin and barley salad. Adapted from Centrum Respo. Nutritional values are estimates.",
      "instructions": [
        "Cook the barley following the packet. Deseed and dice the pumpkin, then cut the turkey into pieces.",
        "Toss the pumpkin and turkey with the olive oil, smoked paprika, garlic powder, cumin, salt and pepper. Roast at 200°C for 18–20 minutes; check that the turkey is fully cooked.",
        "Mix the peanut butter, soy sauce, lemon juice, honey and water. Toast the sunflower seeds in a dry pan.",
        "Arrange the barley, pumpkin and turkey in a bowl. Finish with the dressing, seeds and chopped parsley.",
      ],
      "suggested_seasonings": [],
    },
    "de": {
      "name": "Weißtruthühner-, Kürbis- und Gerstensalat",
      "description":
          "Ein Herbstgericht: warmer Truthahn, Kürbis und Gerstensalat. Angepasst an Centrum Respo. Nährwerte sind Schätzungen.",
      "instructions": [
        "Die Gerste nach dem Packstück kochen, den Kürbis entkernen und dann den Truthahn in Stücke schneiden.",
        "Kürbis und Truthahn mit Olivenöl, geräuchertem Paprika, Knoblauchpulver, Kreuzkümmel, Salz und Pfeffer werfen; Rösten bei 200°C für 18–20 Minuten; prüfen, ob der Truthahn vollständig gekocht ist.",
        "Erdnussbutter, Sojasauce, Zitronensaft, Honig und Wasser mischen und die Sonnenblumenkerne in einer trockenen Pfanne rösten.",
        "Gerste, Kürbis und Truthahn in einer Schüssel anordnen und mit Dressing, Samen und gehackter Petersilie abschließen.",
      ],
      "suggested_seasonings": [],
    },
  },
  "b355be88-0b8b-5874-a582-d81cc84574cc": {
    "source": {
      "name": "Owsianka marchewkowa z orzechami",
      "description":
          "Jesienna propozycja: owsianka marchewkowa z orzechami. Opracowanie na podstawie Centrum Respo. Wartości odżywcze są orientacyjne.",
      "instructions": [
        "Zetrzyj marchew i włóż do rondla z płatkami, rodzynkami, cynamonem, imbirem i goździkami.",
        "Wlej mleko i gotuj łagodnie przez 8–10 minut, mieszając. Gdy trzeba, dolej trochę wody.",
        "Dodaj erytrytol. Przełóż do miski, a po lekkim przestudzeniu dodaj skyr i posiekane orzechy.",
      ],
      "suggested_seasonings": [],
    },
    "en_GB": {
      "name": "Carrot cake porridge with walnuts",
      "description":
          "An autumn dish: carrot cake porridge with walnuts. Adapted from Centrum Respo. Nutritional values are estimates.",
      "instructions": [
        "Grate the carrot into a saucepan with the oats, raisins, cinnamon, ginger and cloves.",
        "Add the milk and simmer for 8–10 minutes, stirring. Add a splash of water if needed.",
        "Stir in the erythritol. Transfer to a bowl, allow to cool slightly, then add the skyr and chopped walnuts.",
      ],
      "suggested_seasonings": [],
    },
    "de": {
      "name": "Karottenkuchenbrei mit Walnüssen",
      "description":
          "Ein Herbstgericht: Karottenkuchenbrei mit Walnüssen. Angepasst an Centrum Respo. Nährwerte sind Schätzungen.",
      "instructions": [
        "Die Karotte mit Hafer, Rosinen, Zimt, Ingwer und Nelken in einen Topf reiben.",
        "Die Milch wird hinzugegeben und unter Rühren für 8–10 Minuten geköchelt. Bei Bedarf ein Spritzer Wasser hinzufügen.",
        "Im Erythrit rühren, in eine Schüssel geben, leicht abkühlen lassen, dann Skyr und gehackte Walnüsse hinzufügen.",
      ],
      "suggested_seasonings": [],
    },
  },
  "2b5a96c1-cb41-5b2a-982e-7555734d91e5": {
    "source": {
      "name": "Quinoa z wołowiną i dynią",
      "description":
          "Jesienna propozycja: quinoa z wołowiną i dynią. Opracowanie na podstawie Centrum Respo. Wartości odżywcze są orientacyjne.",
      "instructions": [
        "Ugotuj komosę według opakowania. Pokrój cebulę, czosnek, dynię i polędwicę.",
        "Na oliwie zeszklij cebulę, dodaj czosnek, a następnie obsmaż wołowinę. Dołóż dynię, paprykę i oregano.",
        "Dodaj passatę i gotowy bulion. Duś przez 10–12 minut, aż dynia i mięso będą miękkie; dopraw solą i pieprzem.",
        "Podaj z komosą i natką pietruszki.",
      ],
      "suggested_seasonings": [],
    },
    "en_GB": {
      "name": "Quinoa with beef and pumpkin",
      "description":
          "An autumn dish: quinoa with beef and pumpkin. Adapted from Centrum Respo. Nutritional values are estimates.",
      "instructions": [
        "Cook the quinoa following the packet. Chop the onion, garlic, pumpkin and beef fillet.",
        "Soften the onion in the olive oil, add the garlic, then brown the beef. Stir in the pumpkin, paprika and oregano.",
        "Pour in the passata and prepared stock. Simmer for 10–12 minutes until the pumpkin and beef are tender; season with salt and pepper.",
        "Serve with the quinoa and parsley.",
      ],
      "suggested_seasonings": [],
    },
    "de": {
      "name": "Quinoa mit Rindfleisch und Kürbis",
      "description":
          "Ein Herbstgericht: Quinoa mit Rindfleisch und Kürbis, angepasst an Centrum Respo, Nährwerte sind Schätzungen.",
      "instructions": [
        "Die Quinoa wird nach dem Packstück gekocht, Zwiebel, Knoblauch, Kürbis und Rindfilet gepflückt.",
        "Die Zwiebel im Olivenöl erweichen, den Knoblauch hinzufügen, dann das Rindfleisch bräunen, Kürbis, Paprika und Oregano rühren.",
        "Gießen Sie die Passata und den zubereiteten Vorrat ein, köcheln Sie 10–12 Minuten, bis der Kürbis und das Rindfleisch zart sind; würzen Sie mit Salz und Pfeffer.",
        "Servieren Sie mit der Quinoa und Petersilie.",
      ],
      "suggested_seasonings": [],
    },
  },
  "36a1771f-37dd-51bd-964c-fc71e1f5e32b": {
    "source": {
      "name": "Meksykańska zupa z dynią i kukurydzą",
      "description":
          "Jesienna propozycja: meksykańska zupa z dynią i kukurydzą. Opracowanie na podstawie Centrum Respo. Wartości odżywcze są orientacyjne.",
      "instructions": [
        "Posiekaj cebulę i czosnek, pokrój dynię i paprykę. Fasolę i kukurydzę odsącz.",
        "Na oliwie zeszklij cebulę z czosnkiem. Dodaj dynię i paprykę, chwilę smaż, po czym wlej gotowy bulion i dodaj suche przyprawy.",
        "Gotuj do miękkości dyni i ostrożnie zblenduj. Na osobnej patelni dokładnie usmaż mielonego indyka, rozdzielając grudki.",
        "Dodaj mięso, fasolę i kukurydzę do zupy i podgrzewaj przez 5–10 minut. Podaj z nachosami, chili i kolendrą.",
      ],
      "suggested_seasonings": [],
    },
    "en_GB": {
      "name": "Mexican pumpkin and sweetcorn soup",
      "description":
          "An autumn dish: mexican pumpkin and sweetcorn soup. Adapted from Centrum Respo. Nutritional values are estimates.",
      "instructions": [
        "Chop the onion and garlic, dice the pumpkin and pepper, and drain the beans and sweetcorn.",
        "Soften the onion and garlic in the olive oil. Add the pumpkin and pepper, fry briefly, then add the prepared stock and dried seasonings.",
        "Simmer until the pumpkin is soft, then blend carefully. Fully cook the turkey mince in a separate pan, breaking up any lumps.",
        "Add the turkey, beans and sweetcorn to the soup and simmer for 5–10 minutes. Serve with the tortilla chips, chilli and coriander.",
      ],
      "suggested_seasonings": [],
    },
    "de": {
      "name": "Mexikanische Kürbis- und Zuckermaissuppe",
      "description":
          "Ein Herbstgericht: mexikanischer Kürbis- und Zuckermaissuppe, angepasst an Centrum Respo, Nährwerte sind Schätzungen.",
      "instructions": [
        "Hacken Sie die Zwiebel und den Knoblauch, würfeln Sie den Kürbis und den Pfeffer und entleeren Sie die Bohnen und den Zuckermais.",
        "Zwiebel und Knoblauch im Olivenöl erweichen, Kürbis und Pfeffer hinzufügen, kurz braten, dann den zubereiteten Stamm und die getrockneten Würzstoffe hinzufügen.",
        "Kochen, bis der Kürbis weich ist, dann mischen Sie vorsichtig. Kochen Sie das Putenhackfleisch vollständig in einer separaten Pfanne und brechen Sie alle Klumpen auf.",
        "Pute, Bohnen und Zuckermais zur Suppe geben und für 5–10 Minuten kochen, mit den Tortillachips, Chili und Koriander servieren.",
      ],
      "suggested_seasonings": [],
    },
  },
  "cbb746b3-22c3-54d7-aaff-fc99dab74f0a": {
    "source": {
      "name": "Gulasz wołowy z dynią",
      "description":
          "Jesienna propozycja: gulasz wołowy z dynią. Opracowanie na podstawie Centrum Respo. Wartości odżywcze są orientacyjne.",
      "instructions": [
