  "416ba64b-5bd8-501b-93e5-1f886ee79ba0": {
    "source": {
      "name": "Pieczona ricotta ze śliwkami",
      "description": "Ciepła ricotta z pieczonymi śliwkami i ich sokiem.",
      "instructions": [
