  "b450d9e5-7294-51f3-9694-a586534baf32": {
    "source": {
      "name": "Tofu w sezamie z groszkiem i marchewką",
      "description":
          "Chrupiące sezamowe tofu z rozgniecionym groszkiem i wstążkami marchewki.",
