      ],
      "suggested_seasonings": [],
    },
    "de": {
      "name": "Apfel- und Karottenhafermuffins",
      "description": "Tender Muffins mit geriebener Karotte und Apfel im Teig.",
      "instructions": [
        "Apfel und Karotte reiben, Eier mit Milch, Öl und Honig pfeifen.",
